// Origin (0,0,0) = elevator shaft centre at ground level. Units = metres. X axis is mirrored vs. the web viewer (Unity is left-handed).
// Every part is a normal GameObject: edit Position / Rotation / Scale in the Inspector.
// Hierarchy: IICT_Building / (1F,2F,3F,RF,Misc) / (Wall,Floor,Ceiling,DoorLeaf,GlassOrRail,...) / part
using UnityEngine; using UnityEditor; using System.Collections.Generic; using System.Globalization;
public static class IICTBuildingBuilder {
 static float F(string s){return float.Parse(s,CultureInfo.InvariantCulture);}
 static Material GetMat(string hex,float op,Dictionary<string,Material> d){
  string key=hex+"_"+Mathf.RoundToInt(op*100); Material m; if(d.TryGetValue(key,out m))return m;
  Shader sh=Shader.Find("Universal Render Pipeline/Lit"); bool urp=sh!=null; if(!urp)sh=Shader.Find("Standard");
  m=new Material(sh); Color c; ColorUtility.TryParseHtmlString("#"+hex,out c); c.a=op; m.color=c; if(urp)m.SetColor("_BaseColor",c);
  if(op<1f){
   if(urp){m.SetFloat("_Surface",1);m.SetFloat("_Blend",0);m.SetFloat("_ZWrite",0);m.SetInt("_SrcBlend",5);m.SetInt("_DstBlend",10);m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");}
   else{m.SetFloat("_Mode",3);m.SetInt("_SrcBlend",5);m.SetInt("_DstBlend",10);m.SetInt("_ZWrite",0);m.EnableKeyword("_ALPHABLEND_ON");}
   m.SetOverrideTag("RenderType","Transparent"); m.renderQueue=3000;
  }
  AssetDatabase.CreateAsset(m,"Assets/IICT/Materials/mat_"+key+".mat"); d[key]=m; return m;}
 static Transform Sub(Transform p,string n,Dictionary<string,Transform> d){
  string k=p.name+"/"+n; Transform t; if(d.TryGetValue(k,out t))return t;
  var g=new GameObject(n); g.transform.SetParent(p,false); d[k]=g.transform; return g.transform;}
 [MenuItem("Tools/IICT/Delete Building")]
 public static void Delete(){ foreach(var t in Resources.FindObjectsOfTypeAll<Transform>()){ if(t!=null && t.parent==null && t.gameObject.scene.IsValid() && t.name.StartsWith("IICT_Building")) Object.DestroyImmediate(t.gameObject); } }
 [MenuItem("Tools/IICT/Build Building")]
 public static void Build(){
  var olds=new List<GameObject>(); foreach(var t in Resources.FindObjectsOfTypeAll<Transform>()){ if(t!=null && t.parent==null && t.gameObject.scene.IsValid() && t.name.StartsWith("IICT_Building")) olds.Add(t.gameObject); }
  foreach(var o in olds){ if(o!=null) Object.DestroyImmediate(o); }
  int count=0;
  AssetDatabase.DeleteAsset("Assets/IICT"); AssetDatabase.CreateFolder("Assets","IICT"); AssetDatabase.CreateFolder("Assets/IICT","Materials"); AssetDatabase.CreateFolder("Assets/IICT","Meshes");
  var root=new GameObject("IICT_Building"); root.transform.position=Vector3.zero;
  var mats=new Dictionary<string,Material>(); var subs=new Dictionary<string,Transform>();
  foreach(var line in DATA.Split('\n')){
   if(line.Length<5)continue; var a=line.Trim().Split('|');
   var par=Sub(Sub(root.transform,a[1],subs),a[2],subs); GameObject go;
   if(a[0]=="B"){
    go=GameObject.CreatePrimitive(PrimitiveType.Cube); go.transform.SetParent(par,false);
    go.transform.localPosition=new Vector3(-F(a[4]),F(a[5]),F(a[6]));
    go.transform.localScale=new Vector3(F(a[7]),F(a[8]),F(a[9]));
    go.transform.localRotation=Quaternion.Euler(0,-F(a[10]),0);
    go.GetComponent<Renderer>().sharedMaterial=GetMat(a[11],F(a[12]),mats);
   } else {
    go=new GameObject(a[3]); go.transform.SetParent(par,false);
    go.transform.localPosition=new Vector3(-F(a[4]),F(a[5]),F(a[6]));
    var vs=new List<Vector3>(); foreach(var s in a[9].Split(';')){var q=s.Split(','); vs.Add(new Vector3(-F(q[0]),F(q[1]),F(q[2])));}
    var ts=new List<int>(); foreach(var s in a[10].Split(';')){var q=s.Split(','); ts.Add(int.Parse(q[0]));ts.Add(int.Parse(q[1]));ts.Add(int.Parse(q[2]));}
    var me=new Mesh(); me.name=a[3]; me.SetVertices(vs); me.SetTriangles(ts,0); me.RecalculateNormals(); me.RecalculateBounds();
    AssetDatabase.CreateAsset(me,"Assets/IICT/Meshes/"+a[3]+".asset");
    go.AddComponent<MeshFilter>().sharedMesh=me; go.AddComponent<MeshRenderer>().sharedMaterial=GetMat(a[7],F(a[8]),mats); go.AddComponent<MeshCollider>().sharedMesh=me;
   }
   go.name=a[3]; count++;
  }
  AssetDatabase.SaveAssets(); Selection.activeGameObject=root;
  Debug.Log("IICT building built. parts="+count+"  script version 2026-11-09T01:09");
 }
